function buildPageFields(product, inventory, reviews) {
  if (product.status === 'error' || inventory.status === 'error') {
    throw new Error('aggregation failed');
  }
  return {
    name: product.name,
    price: product.price,
    inStock: inventory.inStock,
    reviews:
      reviews.status === 'ok'
        ? { averageRating: reviews.averageRating, reviewCount: reviews.reviewCount }
        : { unavailable: true },
  };
}

